 * @param {Object[]} movies - Array of movie objects
 * @returns {number} Average IMDB rating rounded to 1 decimal
 */
function averageImdbRating(movies) {

}

exercises.solution:
function averageImdbRating(movies) {
  const sum = movies.reduce((total, movie) => total + movie.ratings.imdb, 0);
  return Math.round(sum / movies.length * 10) / 10;
}

