 * @returns {Object[]} Array of { title, year } sorted oldest to newest
 */
function sortByYear(movies) {

}

exercises.solution:
function sortByYear(movies) {
  return movies.slice().sort((a, b) => a.year - b.year).map(m => ({ title: m.title, year: m.year }));
}

