exercises.solution:
function mostProfitable(movies) {
  return movies
    .map(m => {
      const revenue = m.boxOffice.domestic + m.boxOffice.international;
      const profit = revenue - m.boxOffice.budget;
      const roi = Math.round(profit / m.boxOffice.budget * 10) / 10;
      return { title: m.title, profit, roi };
    })
    .filter(m => m.profit > 0)
    .sort((a, b) => b.roi - a.roi);
}

